Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsdistribuicaoprodutosWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsdistribuicaoprodutosWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsdistribuicaoprodutosWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFDISTPRODUTOREMESSA" &TFdistProdutoRemessa.FromString(&GridStateFilterValue.Value) &TFdistProdutoRemessa_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTCODIGO" &TFdistCodigo.FromString(&GridStateFilterValue.Value) &TFdistCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTPRODUTODISTDATA" &TFdistProdutoDistData.FromString(&GridStateFilterValue.Value) &TFdistProdutoDistData_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTROTA" &TFdistRota.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTROTA_SEL" &TFdistRota_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOCODIGO" &TFdistProdutoCodigo.FromString(&GridStateFilterValue.Value) &TFdistProdutoCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTPRODUTODESCRICAO" &TFdistProdutoDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTODESCRICAO_SEL" &TFdistProdutoDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOUN" &TFdistProdutoUN.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOUN_SEL" &TFdistProdutoUN_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOQUANTIDADE" &TFdistProdutoQuantidade.FromString(&GridStateFilterValue.Value) &TFdistProdutoQuantidade_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOPESOTOTAL" &TFdistProdutoPesoTotal.FromString(&GridStateFilterValue.Value) &TFdistProdutoPesoTotal_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOVALIDADE" &TFdistProdutoValidade.FromString(&GridStateFilterValue.Value) &TFdistProdutoValidade_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOLOTE" &TFdistProdutoLote.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOLOTE_SEL" &TFdistProdutoLote_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTODISDESTINO" &TFdistProdutoDisDestino.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTODISDESTINO_SEL" &TFdistProdutoDisDestino_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPRODUTOSTATUS_SEL" &TFdistProdutoStatus_SelsJson = &GridStateFilterValue.Value &TFdistProdutoStatus_Sels.FromJson(&TFdistProdutoStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'DISTPRODUTODESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distProdutoDescricao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTPRODUTODISTDATA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distProdutoDistData1.FromString(&GridStateDynamicFilter.Value) &distProdutoDistData_To1.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector1 = !'DISTPRODUTOLOTE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distProdutoLote1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTPRODUTODISDESTINO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distProdutoDisDestino1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTPRODUTOVALIDADE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distProdutoValidade1.FromString(&GridStateDynamicFilter.Value) &distProdutoValidade_To1.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector1 = !'DISTROTA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distRota1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTPRODUTOREMESSA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distProdutoRemessa1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'DISTPRODUTODESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distProdutoDescricao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTPRODUTODISTDATA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distProdutoDistData2.FromString(&GridStateDynamicFilter.Value) &distProdutoDistData_To2.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector2 = !'DISTPRODUTOLOTE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distProdutoLote2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTPRODUTODISDESTINO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distProdutoDisDestino2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTPRODUTOVALIDADE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distProdutoValidade2.FromString(&GridStateDynamicFilter.Value) &distProdutoValidade_To2.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector2 = !'DISTROTA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distRota2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTPRODUTOREMESSA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distProdutoRemessa2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'DISTPRODUTODESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distProdutoDescricao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTPRODUTODISTDATA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distProdutoDistData3.FromString(&GridStateDynamicFilter.Value) &distProdutoDistData_To3.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector3 = !'DISTPRODUTOLOTE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distProdutoLote3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTPRODUTODISDESTINO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distProdutoDisDestino3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTPRODUTOVALIDADE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distProdutoValidade3.FromString(&GridStateDynamicFilter.Value) &distProdutoValidade_To3.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector3 = !'DISTROTA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distRota3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTPRODUTOREMESSA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distProdutoRemessa3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
