&count = 0 For Each trnsdistribuicaoprodutos Order distRota &count += 1 EndFor If not distRota.IsEmpty() &Option = distRota
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
